window.IGCSE_DATA["biology"] = {"name":"Biology","code":"4BI1","kind":"science","totalMarks":180,"papers":[{"id":"1B","name":"Paper 1","duration":"2h","marks":110,"weight":"61.1%","covers":"Content without a ‘B’ reference"},{"id":"2B","name":"Paper 2","duration":"1h 15m","marks":70,"weight":"38.9%","covers":"All content, including ‘B’ references"}],"id":"biology","topics":[{"id":"1","title":"The nature and variety of living organisms","subtopics":[{"id":"a","title":"Characteristics of living organisms","points":[{"ref":"1.1","text":"understand how living organisms share the following characteristics:","paper2only":false,"bullets":["they require nutrition","they respire","they excrete their waste","they respond to their surroundings","they move","they control their internal conditions","they reproduce","they grow and develop"]}]},{"id":"b","title":"Variety of living organisms","points":[{"ref":"1.2","text":"describe the common features shown by eukaryotic organisms: plants, animals, fungi and protoctists","paper2only":false,"details":[{"term":"Plants","text":"these are multicellular organisms; their cells contain chloroplasts and are able to carry out photosynthesis; their cells have cellulose cell walls; they store carbohydrates as starch or sucrose. Examples include flowering plants, such as a cereal (for example, maize), and a herbaceous legume (for example, peas or beans)."},{"term":"Animals","text":"these are multicellular organisms; their cells do not contain chloroplasts and are not able to carry out photosynthesis; they have no cell walls; they usually have nervous co-ordination and are able to move from one place to another; they often store carbohydrate as glycogen. Examples include mammals (for example, humans) and insects (for example, housefly and mosquito)."},{"term":"Fungi","text":"these are organisms that are not able to carry out photosynthesis; their body is usually organised into a mycelium made from thread-like structures called hyphae, which contain many nuclei; some examples are single-celled; their cells have walls made of chitin; they feed by extracellular secretion of digestive enzymes onto food material and absorption of the organic products; this is known as saprotrophic nutrition; they may store carbohydrate as glycogen. Examples include Mucor, which has the typical fungal hyphal structure, and yeast, which is single-celled."},{"term":"Protoctists","text":"these are microscopic single-celled organisms. Some, like Amoeba, that live in pond water, have features like an animal cell, while others, like Chlorella, have chloroplasts and are more like plants. A pathogenic example is Plasmodium, responsible for causing malaria."}]},{"ref":"1.3","text":"describe the common features shown by prokaryotic organisms such as bacteria","paper2only":false,"details":[{"term":"Bacteria","text":"these are microscopic single-celled organisms; they have a cell wall, cell membrane, cytoplasm and plasmids; they lack a nucleus but contain a circular chromosome of DNA; some bacteria can carry out photosynthesis but most feed off other living or dead organisms. Examples include Lactobacillus bulgaricus, a rod-shaped bacterium used in the production of yoghurt from milk, and Pneumococcus, a spherical bacterium that acts as the pathogen causing pneumonia."}]},{"ref":"1.4","text":"understand the term pathogen and know that pathogens may include fungi, bacteria, protoctists or viruses","paper2only":false,"details":[{"term":"Viruses","text":"these are not living organisms. They are small particles, smaller than bacteria; they are parasitic and can reproduce only inside living cells; they infect every type of living organism. They have a wide variety of shapes and sizes; they have no cellular structure but have a protein coat and contain one type of nucleic acid, either DNA or RNA. Examples include the tobacco mosaic virus that causes discolouring of the leaves of tobacco plants by preventing the formation of chloroplasts, the influenza virus that causes ‘flu’ and the HIV virus that causes AIDS."}]}]}]},{"id":"2","title":"Structure and functions in living organisms","subtopics":[{"id":"a","title":"Level of organisation","points":[{"ref":"2.1","text":"describe the levels of organisation in organisms: organelles, cells, tissues, organs and systems","paper2only":false}]},{"id":"b","title":"Cell structure","points":[{"ref":"2.2","text":"describe cell structures, including the nucleus, cytoplasm, cell membrane, cell wall, mitochondria, chloroplasts, ribosomes and vacuole","paper2only":false},{"ref":"2.3","text":"describe the functions of the nucleus, cytoplasm, cell membrane, cell wall, mitochondria, chloroplasts, ribosomes and vacuole","paper2only":false},{"ref":"2.4","text":"know the similarities and differences in the structure of plant and animal cells","paper2only":false},{"ref":"2.5B","text":"explain the importance of cell differentiation in the development of specialised cells","paper2only":true},{"ref":"2.6B","text":"understand the advantages and disadvantages of using stem cells in medicine","paper2only":true}]},{"id":"c","title":"Biological molecules","points":[{"ref":"2.7","text":"identify the chemical elements present in carbohydrates, proteins and lipids (fats and oils)","paper2only":false},{"ref":"2.8","text":"describe the structure of carbohydrates, proteins and lipids as large molecules made up from smaller basic units: starch and glycogen from simple sugars, protein from amino acids, and lipid from fatty acids and glycerol","paper2only":false},{"ref":"2.9","text":"practical: investigate food samples for the presence of glucose, starch, protein and fat","paper2only":false,"practical":true},{"ref":"2.10","text":"understand the role of enzymes as biological catalysts in metabolic reactions","paper2only":false},{"ref":"2.11","text":"understand how temperature changes can affect enzyme function, including changes to the shape of active site","paper2only":false},{"ref":"2.12","text":"practical: investigate how enzyme activity can be affected by changes in temperature","paper2only":false,"practical":true},{"ref":"2.13","text":"understand how enzyme function can be affected by changes in pH altering the active site","paper2only":false},{"ref":"2.14B","text":"practical: investigate how enzyme activity can be affected by changes in pH","paper2only":true,"practical":true}]},{"id":"d","title":"Movement of substances into and out of cells","points":[{"ref":"2.15","text":"understand the processes of diffusion, osmosis and active transport by which substances move into and out of cells","paper2only":false},{"ref":"2.16","text":"understand how factors affect the rate of movement of substances into and out of cells, including the effects of surface area to volume ratio, distance, temperature and concentration gradient","paper2only":false},{"ref":"2.17","text":"practical: investigate diffusion and osmosis using living and non-living systems","paper2only":false,"practical":true}]},{"id":"e","title":"Nutrition","points":[{"ref":"2.18","text":"understand the process of photosynthesis and its importance in the conversion of light energy to chemical energy","paper2only":false,"group":"Flowering plants"},{"ref":"2.19","text":"know the word equation and the balanced chemical symbol equation for photosynthesis","paper2only":false,"group":"Flowering plants"},{"ref":"2.20","text":"understand how varying carbon dioxide concentration, light intensity and temperature affect the rate of photosynthesis","paper2only":false,"group":"Flowering plants"},{"ref":"2.21","text":"describe the structure of the leaf and explain how it is adapted for photosynthesis","paper2only":false,"group":"Flowering plants"},{"ref":"2.22","text":"understand that plants require mineral ions for growth, and that magnesium ions are needed for chlorophyll and nitrate ions are needed for amino acids","paper2only":false,"group":"Flowering plants"},{"ref":"2.23","text":"practical: investigate photosynthesis, showing the evolution of oxygen from a water plant, the production of starch and the requirements of light, carbon dioxide and chlorophyll","paper2only":false,"group":"Flowering plants","practical":true},{"ref":"2.24","text":"understand that a balanced diet should include appropriate proportions of carbohydrate, protein, lipid, vitamins, minerals, water and dietary fibre","paper2only":false,"group":"Humans"},{"ref":"2.25","text":"identify the sources and describe the functions of carbohydrate, protein, lipid (fats and oils), vitamins A, C and D, the mineral ions calcium and iron, water and dietary fibre as components of the diet","paper2only":false,"group":"Humans"},{"ref":"2.26","text":"understand how energy requirements vary with activity levels, age and pregnancy","paper2only":false,"group":"Humans"},{"ref":"2.27","text":"describe the structure and function of the human alimentary canal, including the mouth, oesophagus, stomach, small intestine (duodenum and ileum), large intestine (colon and rectum) and pancreas","paper2only":false,"group":"Humans"},{"ref":"2.28","text":"understand how food is moved through the gut by peristalsis","paper2only":false,"group":"Humans"},{"ref":"2.29","text":"understand the role of digestive enzymes, including the digestion of starch to glucose by amylase and maltase, the digestion of proteins to amino acids by proteases and the digestion of lipids to fatty acids and glycerol by lipases","paper2only":false,"group":"Humans"},{"ref":"2.30","text":"understand that bile is produced by the liver and stored in the gall bladder","paper2only":false,"group":"Humans"},{"ref":"2.31","text":"understand the role of bile in neutralising stomach acid and emulsifying lipids","paper2only":false,"group":"Humans"},{"ref":"2.32","text":"understand how the small intestine is adapted for absorption, including the structure of a villus","paper2only":false,"group":"Humans"},{"ref":"2.33B","text":"practical: investigate the energy content in a food sample","paper2only":true,"group":"Humans","practical":true}]},{"id":"f","title":"Respiration","points":[{"ref":"2.34","text":"understand how the process of respiration produces ATP in living organisms","paper2only":false},{"ref":"2.35","text":"know that ATP provides energy for cells","paper2only":false},{"ref":"2.36","text":"describe the differences between aerobic and anaerobic respiration","paper2only":false},{"ref":"2.37","text":"know the word equation and the balanced chemical symbol equation for aerobic respiration in living organisms","paper2only":false},{"ref":"2.38","text":"know the word equation for anaerobic respiration in plants and in animals","paper2only":false},{"ref":"2.39","text":"practical: investigate the evolution of carbon dioxide and heat from respiring seeds or other suitable living organisms","paper2only":false,"practical":true}]},{"id":"g","title":"Gas exchange","points":[{"ref":"2.40B","text":"understand the role of diffusion in gas exchange","paper2only":true,"group":"Flowering plants"},{"ref":"2.41B","text":"understand gas exchange (of carbon dioxide and oxygen) in relation to respiration and photosynthesis","paper2only":true,"group":"Flowering plants"},{"ref":"2.42B","text":"understand how the structure of the leaf is adapted for gas exchange","paper2only":true,"group":"Flowering plants"},{"ref":"2.43B","text":"describe the role of stomata in gas exchange","paper2only":true,"group":"Flowering plants"},{"ref":"2.44B","text":"understand how respiration continues during the day and night, but that the net exchange of carbon dioxide and oxygen depends on the intensity of light","paper2only":true,"group":"Flowering plants"},{"ref":"2.45B","text":"practical: investigate the effect of light on net gas exchange from a leaf, using hydrogen-carbonate indicator","paper2only":true,"group":"Flowering plants","practical":true},{"ref":"2.46","text":"describe the structure of the thorax, including the ribs, intercostal muscles, diaphragm, trachea, bronchi, bronchioles, alveoli and pleural membranes","paper2only":false,"group":"Humans"},{"ref":"2.47","text":"understand the role of the intercostal muscles and the diaphragm in ventilation","paper2only":false,"group":"Humans"},{"ref":"2.48","text":"explain how alveoli are adapted for gas exchange by diffusion between air in the lungs and blood in capillaries","paper2only":false,"group":"Humans"},{"ref":"2.49","text":"understand the biological consequences of smoking in relation to the lungs and the circulatory system, including coronary heart disease","paper2only":false,"group":"Humans"},{"ref":"2.50","text":"practical: investigate breathing in humans, including the release of carbon dioxide and the effect of exercise","paper2only":false,"group":"Humans","practical":true}]},{"id":"h","title":"Transport","points":[{"ref":"2.51","text":"understand why simple, unicellular organisms can rely on diffusion for movement of substances in and out of the cell","paper2only":false},{"ref":"2.52","text":"understand the need for a transport system in multicellular organisms","paper2only":false},{"ref":"2.53","text":"describe the role of phloem in transporting sucrose and amino acids between the leaves and other parts of the plant","paper2only":false,"group":"Flowering plants"},{"ref":"2.54","text":"describe the role of xylem in transporting water and mineral ions from the roots to other parts of the plant","paper2only":false,"group":"Flowering plants"},{"ref":"2.55B","text":"understand how water is absorbed by root hair cells","paper2only":true,"group":"Flowering plants"},{"ref":"2.56B","text":"understand that transpiration is the evaporation of water from the surface of a plant","paper2only":true,"group":"Flowering plants"},{"ref":"2.57B","text":"understand how the rate of transpiration is affected by changes in humidity, wind speed, temperature and light intensity","paper2only":true,"group":"Flowering plants"},{"ref":"2.58B","text":"practical: investigate the role of environmental factors in determining the rate of transpiration from a leafy shoot","paper2only":true,"group":"Flowering plants","practical":true},{"ref":"2.59","text":"describe the composition of the blood: red blood cells, white blood cells, platelets and plasma","paper2only":false,"group":"Humans"},{"ref":"2.60","text":"understand the role of plasma in the transport of carbon dioxide, digested food, urea, hormones and heat energy","paper2only":false,"group":"Humans"},{"ref":"2.61","text":"understand how adaptations of red blood cells make them suitable for the transport of oxygen, including shape, the absence of a nucleus and the presence of haemoglobin","paper2only":false,"group":"Humans"},{"ref":"2.62","text":"understand how the immune system responds to disease using white blood cells, illustrated by phagocytes ingesting pathogens and lymphocytes releasing antibodies specific to the pathogen","paper2only":false,"group":"Humans"},{"ref":"2.63B","text":"understand how vaccination results in the manufacture of memory cells, which enable future antibody production to the pathogen to occur sooner, faster and in greater quantity","paper2only":true,"group":"Humans"},{"ref":"2.64B","text":"understand how platelets are involved in blood clotting, which prevents blood loss and the entry of micro-organisms","paper2only":true,"group":"Humans"},{"ref":"2.65","text":"describe the structure of the heart and how it functions","paper2only":false,"group":"Humans"},{"ref":"2.66","text":"explain how the heart rate changes during exercise and under the influence of adrenaline","paper2only":false,"group":"Humans"},{"ref":"2.67","text":"understand how factors may increase the risk of developing coronary heart disease","paper2only":false,"group":"Humans"},{"ref":"2.68","text":"understand how the structure of arteries, veins and capillaries relate to their function","paper2only":false,"group":"Humans"},{"ref":"2.69","text":"understand the general structure of the circulation system, including the blood vessels to and from the heart and lungs, liver and kidneys","paper2only":false,"group":"Humans"}]},{"id":"i","title":"Excretion","points":[{"ref":"2.70","text":"understand the origin of carbon dioxide and oxygen as waste products of metabolism and their loss from the stomata of a leaf","paper2only":false,"group":"Flowering plants"},{"ref":"2.71","text":"know the excretory products of the lungs, kidneys and skin (organs of excretion)","paper2only":false,"group":"Humans"},{"ref":"2.72B","text":"understand how the kidney carries out its roles of excretion and osmoregulation","paper2only":true,"group":"Humans"},{"ref":"2.73B","text":"describe the structure of the urinary system, including the kidneys, ureters, bladder and urethra","paper2only":true,"group":"Humans"},{"ref":"2.74B","text":"describe the structure of a nephron, including the Bowman’s capsule and glomerulus, convoluted tubules, loop of Henle and collecting duct","paper2only":true,"group":"Humans"},{"ref":"2.75B","text":"describe ultrafiltration in the Bowman’s capsule and the composition of the glomerular filtrate","paper2only":true,"group":"Humans"},{"ref":"2.76B","text":"understand how water is reabsorbed into the blood from the collecting duct","paper2only":true,"group":"Humans"},{"ref":"2.77B","text":"understand why selective reabsorption of glucose occurs at the proximal convoluted tubule","paper2only":true,"group":"Humans"},{"ref":"2.78B","text":"describe the role of ADH in regulating the water content of the blood","paper2only":true,"group":"Humans"},{"ref":"2.79B","text":"understand that urine contains water, urea and ions","paper2only":true,"group":"Humans"}]},{"id":"j","title":"Co-ordination and response","points":[{"ref":"2.80","text":"understand how organisms are able to respond to changes in their environment","paper2only":false},{"ref":"2.81","text":"understand that homeostasis is the maintenance of a constant internal environment, and that body water content and body temperature are both examples of homeostasis","paper2only":false},{"ref":"2.82","text":"understand that a co-ordinated response requires a stimulus, a receptor and an effector","paper2only":false},{"ref":"2.83","text":"understand that plants respond to stimuli","paper2only":false,"group":"Flowering plants"},{"ref":"2.84","text":"describe the geotropic and phototropic responses of roots and stems","paper2only":false,"group":"Flowering plants"},{"ref":"2.85","text":"understand the role of auxin in the phototropic response of stems","paper2only":false,"group":"Flowering plants"},{"ref":"2.86","text":"describe how nervous and hormonal communication control responses and understand the differences between the two systems","paper2only":false,"group":"Humans"},{"ref":"2.87","text":"understand that the central nervous system consists of the brain and spinal cord and is linked to sense organs by nerves","paper2only":false,"group":"Humans"},{"ref":"2.88","text":"understand that stimulation of receptors in the sense organs sends electrical impulses along nerves into and out of the central nervous system, resulting in rapid responses","paper2only":false,"group":"Humans"},{"ref":"2.89","text":"understand the role of neurotransmitters at synapses","paper2only":false,"group":"Humans"},{"ref":"2.90","text":"describe the structure and functioning of a simple reflex arc illustrated by the withdrawal of a finger from a hot object","paper2only":false,"group":"Humans"},{"ref":"2.91","text":"describe the structure and function of the eye as a receptor","paper2only":false,"group":"Humans"},{"ref":"2.92","text":"understand the function of the eye in focusing on near and distant objects, and in responding to changes in light intensity","paper2only":false,"group":"Humans"},{"ref":"2.93","text":"describe the role of the skin in temperature regulation, with reference to sweating, vasoconstriction and vasodilation","paper2only":false,"group":"Humans"},{"ref":"2.94","text":"understand the sources, roles and effects of the following hormones: adrenaline, insulin, testosterone, progesterone and oestrogen","paper2only":false,"group":"Humans"},{"ref":"2.95B","text":"understand the sources, roles and effects of the following hormones: ADH, FSH and LH","paper2only":true,"group":"Humans"}]}]},{"id":"3","title":"Reproduction and inheritance","subtopics":[{"id":"a","title":"Reproduction","points":[{"ref":"3.1","text":"understand the differences between sexual and asexual reproduction","paper2only":false},{"ref":"3.2","text":"understand that fertilisation involves the fusion of a male and female gamete to produce a zygote that undergoes cell division and develops into an embryo","paper2only":false},{"ref":"3.3","text":"describe the structures of an insect-pollinated and a wind-pollinated flower and explain how each is adapted for pollination","paper2only":false,"group":"Flowering plants"},{"ref":"3.4","text":"understand that the growth of the pollen tube followed by fertilisation leads to seed and fruit formation","paper2only":false,"group":"Flowering plants"},{"ref":"3.5","text":"practical: investigate the conditions needed for seed germination","paper2only":false,"group":"Flowering plants","practical":true},{"ref":"3.6","text":"understand how germinating seeds utilise food reserves until the seedling can carry out photosynthesis","paper2only":false,"group":"Flowering plants"},{"ref":"3.7","text":"understand that plants can reproduce asexually by natural methods (illustrated by runners) and by artificial methods (illustrated by cuttings)","paper2only":false,"group":"Flowering plants"},{"ref":"3.8","text":"understand how the structure of the male and female reproductive systems are adapted for their functions","paper2only":false,"group":"Humans"},{"ref":"3.9","text":"understand the roles of oestrogen and progesterone in the menstrual cycle","paper2only":false,"group":"Humans"},{"ref":"3.10B","text":"understand the roles of FSH and LH in the menstrual cycle","paper2only":true,"group":"Humans"},{"ref":"3.11","text":"describe the role of the placenta in the nutrition of the developing embryo","paper2only":false,"group":"Humans"},{"ref":"3.12","text":"understand how the developing embryo is protected by amniotic fluid","paper2only":false,"group":"Humans"},{"ref":"3.13","text":"understand the roles of oestrogen and testosterone in the development of secondary sexual characteristics","paper2only":false,"group":"Humans"}]},{"id":"b","title":"Inheritance","points":[{"ref":"3.14","text":"understand that the genome is the entire DNA of an organism and that a gene is a section of a molecule of DNA that codes for a specific protein","paper2only":false},{"ref":"3.15","text":"understand that the nucleus of a cell contains chromosomes on which genes are located","paper2only":false},{"ref":"3.16B","text":"describe a DNA molecule as two strands coiled to form a double helix, the strands being linked by a series of paired bases: adenine (A) with thymine (T), and cytosine (C) with guanine (G)","paper2only":true},{"ref":"3.17B","text":"understand that an RNA molecule is single stranded and contains uracil (U) instead of thymine (T)","paper2only":true},{"ref":"3.18B","text":"describe the stages of protein synthesis including transcription and translation, including the role of mRNA, ribosomes, tRNA, codons and anticodons","paper2only":true},{"ref":"3.19","text":"understand how genes exist in alternative forms called alleles which give rise to differences in inherited characteristics","paper2only":false},{"ref":"3.20","text":"understand the meaning of the terms: dominant, recessive, homozygous, heterozygous, phenotype, and genotype","paper2only":false},{"ref":"3.21B","text":"understand the meaning of the term codominance","paper2only":true},{"ref":"3.22","text":"understand that most phenotypic features are the result of polygenic inheritance rather than single genes","paper2only":false},{"ref":"3.23","text":"describe patterns of monohybrid inheritance using a genetic diagram","paper2only":false},{"ref":"3.24","text":"understand how to interpret family pedigrees","paper2only":false},{"ref":"3.25","text":"predict probabilities of outcomes from monohybrid crosses","paper2only":false},{"ref":"3.26","text":"understand how the sex of a person is controlled by one pair of chromosomes, XX in a female and XY in a male","paper2only":false},{"ref":"3.27","text":"describe the determination of the sex of offspring at fertilisation, using a genetic diagram","paper2only":false},{"ref":"3.28","text":"understand how division of a diploid cell by mitosis produces two cells that contain identical sets of chromosomes","paper2only":false},{"ref":"3.29","text":"understand that mitosis occurs during growth, repair, cloning and asexual reproduction","paper2only":false},{"ref":"3.30","text":"understand how division of a cell by meiosis produces four cells, each with half the number of chromosomes, and that this results in the formation of genetically different haploid gametes","paper2only":false},{"ref":"3.31","text":"understand how random fertilisation produces genetic variation of offspring","paper2only":false},{"ref":"3.32","text":"know that in human cells the diploid number of chromosomes is 46 and the haploid number is 23","paper2only":false},{"ref":"3.33","text":"understand that variation within a species can be genetic, environmental, or a combination of both","paper2only":false},{"ref":"3.34","text":"understand that mutation is a rare, random change in genetic material that can be inherited","paper2only":false},{"ref":"3.35B","text":"understand how a change in DNA can affect the phenotype by altering the sequence of amino acids in a protein","paper2only":true},{"ref":"3.36B","text":"understand how most genetic mutations have no effect on the phenotype, some have a small effect and rarely do they have a significant effect","paper2only":true},{"ref":"3.37B","text":"understand that the incidence of mutations can be increased by exposure to ionising radiation (for example, gamma rays, x-rays and ultraviolet rays) and some chemical mutagens (for example, chemicals in tobacco)","paper2only":true},{"ref":"3.38","text":"explain Darwin’s theory of evolution by natural selection","paper2only":false},{"ref":"3.39","text":"understand how resistance to antibiotics can increase in bacterial populations, and appreciate how such an increase can lead to infections being difficult to control","paper2only":false}]}]},{"id":"4","title":"Ecology and the environment","subtopics":[{"id":"a","title":"The organism in the environment","points":[{"ref":"4.1","text":"understand the terms population, community, habitat and ecosystem","paper2only":false},{"ref":"4.2","text":"practical: investigate the population size of an organism in two different areas using quadrats","paper2only":false,"practical":true},{"ref":"4.3B","text":"understand the term biodiversity","paper2only":true},{"ref":"4.4B","text":"practical: investigate the distribution of organisms in their habitats and measure biodiversity using quadrats","paper2only":true,"practical":true},{"ref":"4.5","text":"understand how abiotic and biotic factors affect the population size and distribution of organisms","paper2only":false}]},{"id":"b","title":"Feeding relationships","points":[{"ref":"4.6","text":"understand the names given to different trophic levels, including producers, primary, secondary and tertiary consumers and decomposers","paper2only":false},{"ref":"4.7","text":"understand the concepts of food chains, food webs, pyramids of number, pyramids of biomass and pyramids of energy transfer","paper2only":false},{"ref":"4.8","text":"understand the transfer of substances and energy along a food chain","paper2only":false},{"ref":"4.9","text":"understand why only about 10% of energy is transferred from one trophic level to the next","paper2only":false}]},{"id":"c","title":"Cycles within ecosystems","points":[{"ref":"4.10","text":"describe the stages in the carbon cycle, including respiration, photosynthesis, decomposition and combustion","paper2only":false},{"ref":"4.11B","text":"describe the stages in the nitrogen cycle, including the roles of nitrogen fixing bacteria, decomposers, nitrifying bacteria and denitrifying bacteria (specific names of bacteria are not required)","paper2only":true}]},{"id":"d","title":"Human influences on the environment","points":[{"ref":"4.12","text":"understand the biological consequences of pollution of air by sulfur dioxide and carbon monoxide","paper2only":false},{"ref":"4.13","text":"understand that water vapour, carbon dioxide, nitrous oxide, methane and CFCs are greenhouse gases","paper2only":false},{"ref":"4.14","text":"understand how human activities contribute to greenhouse gases","paper2only":false},{"ref":"4.15","text":"understand how an increase in greenhouse gases results in an enhanced greenhouse effect and that this may lead to global warming and its consequences","paper2only":false},{"ref":"4.16","text":"understand the biological consequences of pollution of water by sewage","paper2only":false},{"ref":"4.17","text":"understand the biological consequences of eutrophication caused by leached minerals from fertiliser","paper2only":false},{"ref":"4.18B","text":"understand the effects of deforestation, including leaching, soil erosion, disturbance of evapotranspiration and the carbon cycle, and the balance of atmospheric gases","paper2only":true}]}]},{"id":"5","title":"Use of biological resources","subtopics":[{"id":"a","title":"Food production","points":[{"ref":"5.1","text":"describe how glasshouses and polythene tunnels can be used to increase the yield of certain crops","paper2only":false},{"ref":"5.2","text":"understand the effects on crop yield of increased carbon dioxide and increased temperature in glasshouses","paper2only":false},{"ref":"5.3","text":"understand how the use of fertiliser can increase crop yield","paper2only":false},{"ref":"5.4","text":"understand the reasons for pest control and the advantages and disadvantages of using pesticides and biological control with crop plants Micro-organisms","paper2only":false},{"ref":"5.5","text":"understand the role of yeast in the production of food including bread","paper2only":false},{"ref":"5.6","text":"practical: investigate the role of anaerobic respiration by yeast in different conditions","paper2only":false,"practical":true},{"ref":"5.7","text":"understand the role of bacteria (Lactobacillus) in the production of yoghurt","paper2only":false},{"ref":"5.8","text":"understand the use of an industrial fermenter and explain the need to provide suitable conditions in the fermenter, including aseptic precautions, nutrients, optimum temperature and pH, oxygenation and agitation, for the growth of micro- organisms Fish farming","paper2only":false},{"ref":"5.9B","text":"understand the methods used to farm large numbers of fish to provide a source of protein, including maintaining water quality, controlling intraspecific and interspecific predation, controlling disease, removing waste products, controlling the quality and frequency of feeding, and selective breeding","paper2only":true}]},{"id":"b","title":"Selective breeding","points":[{"ref":"5.10","text":"understand how selective breeding can develop plants with desired characteristics","paper2only":false},{"ref":"5.11","text":"understand how selective breeding can develop animals with desired characteristics","paper2only":false}]},{"id":"c","title":"Genetic modification (genetic engineering)","points":[{"ref":"5.12","text":"understand how restriction enzymes are used to cut DNA at specific sites and ligase enzymes are used to join pieces of DNA together","paper2only":false},{"ref":"5.13","text":"understand how plasmids and viruses can act as vectors, which take up pieces of DNA, and then insert this recombinant DNA into other cells","paper2only":false},{"ref":"5.14","text":"understand how large amounts of human insulin can be manufactured from genetically modified bacteria that are grown in a fermenter","paper2only":false},{"ref":"5.15","text":"understand how genetically modified plants can be used to improve food production","paper2only":false},{"ref":"5.16","text":"understand that the term transgenic means the transfer of genetic material from one species to a different species","paper2only":false}]},{"id":"d","title":"Cloning","points":[{"ref":"5.17B","text":"describe the process of micropropagation (tissue culture) in which explants are grown in vitro","paper2only":true},{"ref":"5.18B","text":"understand how micropropagation can be used to produce commercial quantities of genetically identical plants with desirable characteristics","paper2only":true},{"ref":"5.19B","text":"describe the stages in the production of cloned mammals involving the introduction of a diploid nucleus from a mature cell into an enucleated egg cell, illustrated by Dolly the sheep","paper2only":true},{"ref":"5.20B","text":"understand how cloned transgenic animals can be used to produce human proteins","paper2only":true}]}]}]};
